arguments.command:
cd /tmp/friends-phoebe && git rev-parse a0ed2364 && cat > /tmp/friends-git-askpass.sh <<'EOF'
#!/bin/sh
case "$1" in
  *Username*) printf '%s' "x-access-token" ;;
  *Password*) printf '%s' "$GITHUB_TOKEN" ;;
  *) printf '%s' "" ;;
esac
EOF
chmod +x /tmp/friends-git-askpass.sh && echo askpass-ready
